return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'ml_IN','project-id-version'=>'Events Manager','pot-creation-date'=>'2026-11-16T04:45:03+00:00','po-revision-date'=>'2026-11-15 04:34:21+0000','x-generator'=>'Pixelite GlotPress Sync','messages'=>[' Maximum size permitted by WordPress is %s.'=>' WordPress അനുവദിക്കുന്ന പരമാവധി വലുപ്പം %s ആണ്.',' is required.'=>' ആവശ്യമാണ്.','"%1$s" could not be created: %2$s'=>'“%1$s” സൃഷ്ടിക്കാൻ കഴിഞ്ഞില്ല: %2$s','"%1$s" is not a field. Fields: %2$s.'=>'“%1$s” ഒരു ഫീൽഡ് അല്ല. ഫീൽഡുകൾ: %2$s.','"%s" is neither a media ID nor a web address that can be reached.'=>'“%s” ഒരു മീഡിയ ഐഡിയോ ലഭ്യമാകുന്ന വെബ് വിലാസമോ അല്ല.','"All events" link text'=>'"എല്ലാ ഇവന്റുകളും" ലിങ്ക് ടെക്സ്റ്റ്','#s will be replaced by the date format below'=>'#s എന്നത് താഴെയുള്ള തീയതി ഫോർമാറ്റ് കൊണ്ട് മാറ്റിസ്ഥാപിക്കും','%1$s could not be updated yet, and Events Manager will keep retrying in the background: %2$s'=>'%1$s ഇതുവരെ അപ്ഡേറ്റ് ചെയ്യാൻ കഴിഞ്ഞില്ല, Events Manager പശ്ചാത്തലത്തിൽ വീണ്ടും ശ്രമിച്ചുകൊണ്ടിരിക്കും: %2$s','%1$s of %2$s'=>'%2$s ൽ %1$s','%1$s recommends %2$s version %3$s or greater installed. Earlier versions may cause unexpected issues.'=>'%1$s, %2$s പതിപ്പ് %3$s അല്ലെങ്കിൽ അതിന് മുകളിലുള്ളത് ഇൻസ്റ്റാൾ ചെയ്യാൻ ശുപാർശ ചെയ്യുന്നു. പഴയ പതിപ്പുകൾ അപ്രതീക്ഷിത പ്രശ്നങ്ങൾക്ക് കാരണമായേക്കാം.','%1$s requires %2$s version %3$s or greater installed.'=>'%1$s-ന്, %2$s പതിപ്പ് %3$s അല്ലെങ്കിൽ അതിന് മുകളിലുള്ളത് ഇൻസ്റ്റാൾ ചെയ്തിരിക്കണം.','%1$s was updated, but the result could not be stored: %2$s'=>'%1$s അപ്ഡേറ്റ് ചെയ്തു, പക്ഷേ ഫലം സംഭരിക്കാൻ കഴിഞ്ഞില്ല: %2$s','%1$s will be set up automatically on %2$s.'=>'%1$s %2$s ന് സ്വയമേവ സജ്ജീകരിക്കും.','%1$s: %2$d rows imported, %3$d skipped.'=>'%1$s: %2$d വരികൾ ഇമ്പോർട്ട് ചെയ്തു, %3$d ഒഴിവാക്കി.','%d Attendees'=>'%d പങ്കെടുക്കുന്നവർ','%d Pattern'=>'%d പാറ്റേൺ' . "\0" . '%d പാറ്റേണുകൾ','%d Spaces'=>'%d സീറ്റുകൾ','%d Tickets'=>'%d ടിക്കറ്റുകൾ','%d date'=>'%d തീയതി' . "\0" . '%d തീയതികൾ','%d events have been %s as they no longer match the recurrence pattern.'=>'%d ഇവന്റുകൾ ആവർത്തന പാറ്റേണുമായി ഇനി യോജിക്കാത്തതിനാൽ %s.','%d more rows are not listed.'=>'%d വരികൾ കൂടി പട്ടികപ്പെടുത്തിയിട്ടില്ല.','%d potentially orphaned events have been found.'=>'അനാഥമായിരിക്കാൻ സാധ്യതയുള്ള %d ഇവന്റുകൾ കണ്ടെത്തി.','%d space'=>'%d സീറ്റ്' . "\0" . '%d സീറ്റുകൾ','%d ticket belongs to a recurring event or series pass; each date of the migrated recurring event gets its own copy of the ticket, and each series pass order becomes one booking per date.'=>'%d ടിക്കറ്റ് ഒരു ആവർത്തിക്കുന്ന ഇവന്റിന്റെയോ സീരീസ് പാസിന്റെയോ ഭാഗമാണ്; മൈഗ്രേറ്റ് ചെയ്ത ആവർത്തിക്കുന്ന ഇവന്റിന്റെ ഓരോ തിയതിക്കും ടിക്കറ്റിന്റെ സ്വന്തം പകർപ്പ് ലഭിക്കും, ഓരോ സീരീസ് പാസ് ഓർഡറും ഓരോ തിയതിക്കും ഓരോ ബുക്കിംഗ് ആയി മാറും.' . "\0" . '%d ടിക്കറ്റുകൾ ആവർത്തിക്കുന്ന ഇവന്റുകളുടെയോ സീരീസ് പാസുകളുടെയോ ഭാഗമാണ്; മൈഗ്രേറ്റ് ചെയ്ത ആവർത്തിക്കുന്ന ഇവന്റിന്റെ ഓരോ തിയതിക്കും ടിക്കറ്റിന്റെ സ്വന്തം പകർപ്പ് ലഭിക്കും, ഓരോ സീരീസ് പാസ് ഓർഡറും ഓരോ തിയതിക്കും ഓരോ ബുക്കിംഗ് ആയി മാറും.','%d will be replaced by a number.'=>'%d ഒരു സംഖ്യ കൊണ്ട് മാറ്റിസ്ഥാപിക്കപ്പെടും.','%s'=>'%s','%s (the link is provided after booking)'=>'%s (ബുക്കിംഗിന് ശേഷം ലിങ്ക് നൽകും)','%s (the link is provided once your booking is confirmed)'=>'%s (നിങ്ങളുടെ ബുക്കിംഗ് സ്ഥിരീകരിച്ചാൽ ലിങ്ക് നൽകും)','%s (your booking does not include virtual access)'=>'%s (നിങ്ങളുടെ ബുക്കിംഗിൽ വെർച്വൽ ആക്സസ് ഉൾപ്പെടുന്നില്ല)','%s Advanced Options'=>'അഡ്വാൻസ്ഡ് ഓപ്ഷനുകൾ: %s','%s App ID'=>'%s ആപ്പ് ഐഡി','%s App Secret'=>'%s ആപ്പ് സീക്രട്ട്','%s Attributes'=>'%s വിശേഷണങ്ങൾ','%s Between'=>'%s ഇടയിൽ','%s Capabilities'=>'%s കഴിവുകൾ','%s Error. Try again?'=>'%s പിശക്. വീണ്ടും ശ്രമിക്കണോ?','%s Excerpts'=>'%s രത്നച്ചുരുക്കങ്ങൾ','%s ID'=>'%s ഐഡി','%s List Formats'=>'%s പട്ടിക ഫോർമാറ്റുകൾ','%s List/Archives'=>'%s പട്ടിക/ശേഖരങ്ങൾ','%s Options'=>'%s ഓപ്ഷനുകൾ','%s Page'=>'%s താള്‍','%s Pages'=>'%s പേജുകൾ','%s Preview Mode'=>'%s പ്രിവ്യൂ മോഡ്','%s Recurrences'=>'%s ആവർത്തനങ്ങൾ','%s Rows'=>'%s നിരകൾ','%s Settings'=>'%s ക്രമീകരണങ്ങൾ','%s Span Between'=>'%s ഇടയിലുള്ള കാലയളവ്','%s Status'=>'%s സ്ഥിതി','%s Submitted'=>'%s സമർപ്പിച്ചു','%s URL'=>'%s യുആര്‍എല്‍','%s added the event %s'=>'%s ഇവന്റ് %s ചേർത്തു','%s added the event %s to %s.'=>'%s ഇവന്റ് %s %s-ലേക്ക് ചേർത്തു.','%s allows you to modify some or all of the formats used by Events Manager to generate your content. You can choose to override default formats and customize them to your needs. You do not lose your previously defined custom formats should you enable/disable %s or choose to not override a certain set of formats, they\'ll appear again once you enable %s again for that content.'=>'നിങ്ങളുടെ ഉള്ളടക്കം സൃഷ്ടിക്കാൻ Events Manager ഉപയോഗിക്കുന്ന ഫോർമാറ്റുകളിൽ ചിലതോ എല്ലാമോ മാറ്റം വരുത്താൻ %s നിങ്ങളെ അനുവദിക്കുന്നു. സ്വാഭാവിക ഫോർമാറ്റുകൾ അസാധുവാക്കി നിങ്ങളുടെ ആവശ്യത്തിനനുസരിച്ച് ഇഷ്ടാനുസൃതമാക്കാം. %s പ്രവർത്തനക്ഷമമാക്കുകയോ പ്രവർത്തനരഹിതമാക്കുകയോ ചെയ്താലും, ഒരു കൂട്ടം ഫോർമാറ്റുകൾ അസാധുവാക്കേണ്ടെന്ന് തീരുമാനിച്ചാലും, നിങ്ങൾ മുമ്പ് നിർവചിച്ച ഇഷ്ടാനുസൃത ഫോർമാറ്റുകൾ നഷ്ടപ്പെടില്ല; ആ ഉള്ളടക്കത്തിനായി %s വീണ്ടും പ്രവർത്തനക്ഷമമാക്കുമ്പോൾ അവ വീണ്ടും ദൃശ്യമാകും.','%s are a <a href="%s" target="_blank">WordPress custom taxonomy</a>.'=>'%s ഒരു <a href="%s" target="_blank">WordPress ഇഷ്‌ടാനുസൃത ടാക്സോണമി</a> ആണ്.','%s are also accepted, for example %s equals 1 month and 12 hours before the event starts.'=>'%s എന്നിവയും സ്വീകരിക്കും, ഉദാഹരണത്തിന് %s എന്നാൽ ഇവന്റ് ആരംഭിക്കുന്നതിന് 1 മാസവും 12 മണിക്കൂറും മുമ്പ് എന്നാണ്.','%s belonging to other sub-sites will have an extra slug prepended to it so that your main site can differentiate between its own %s and those belonging to other sites in your network.'=>'മറ്റ് ഉപ-സൈറ്റുകളുടേതായ %s-ന് ഒരു അധിക സ്ലഗ് മുന്നിൽ ചേർക്കും, അങ്ങനെ പ്രധാന സൈറ്റിന് സ്വന്തം %s-ഉം നിങ്ങളുടെ നെറ്റ്‌വർക്കിലെ മറ്റ് സൈറ്റുകളുടേതും തമ്മിൽ വേർതിരിച്ചറിയാനാകും.','%s can be displayed just like normal WordPress custom taxonomies in an archive-style format, however Events Manager by default allows you to completely change the standard look of these archives and use our own <a href="%s">custom formatting</a> methods.'=>'%s സാധാരണ WordPress ഇഷ്‌ടാനുസൃത ടാക്സോണമികളെപ്പോലെ ഒരു ശേഖര രൂപത്തിൽ കാണിക്കാം, എന്നാൽ Events Manager ഈ ശേഖരങ്ങളുടെ സാധാരണ രൂപം പൂർണ്ണമായും മാറ്റാനും ഞങ്ങളുടെ സ്വന്തം <a href="%s">ഇഷ്‌ടാനുസൃത ഫോർമാറ്റിംഗ്</a> രീതികൾ ഉപയോഗിക്കാനും സ്വാഭാവികമായി അനുവദിക്കുന്നു.','%s cannot be used for a hybrid event, because it gives every booking virtual access.'=>'ഓരോ ബുക്കിംഗിനും വെർച്വൽ ആക്സസ് നൽകുന്നതിനാൽ %s ഹൈബ്രിഡ് ഇവന്റിന് ഉപയോഗിക്കാൻ കഴിയില്ല.','%s could not be deleted'=>'%s ഇല്ലാതാക്കാൻ കഴിഞ്ഞില്ല','%s could not be deleted.'=>'%s ഇല്ലാതാക്കാൻ കഴിഞ്ഞില്ല.','%s created.'=>'%s ഉണ്ടാക്കി.','%s custom post types can have archives, just like normal WordPress posts. If enabled, should you visit your base slug url %s and you will see an post-formatted archive of previous %s'=>'%s കസ്റ്റം പോസ്റ്റ് തരങ്ങൾക്ക് സാധാരണ WordPress പോസ്റ്റുകളെപ്പോലെ ആർക്കൈവുകൾ ഉണ്ടാകാം. പ്രവർത്തനക്ഷമമാക്കിയാൽ, നിങ്ങളുടെ അടിസ്ഥാന സ്ലഗ് യുആർഎൽ %s സന്ദർശിക്കുമ്പോൾ മുൻപത്തെ %s ന്റെ പോസ്റ്റ്-ഫോർമാറ്റ് ചെയ്ത ആർക്കൈവ് കാണാം','%s deleted'=>'%s ഇല്ലാതാക്കി','%s excerpt'=>'%s രത്നച്ചുരുക്കം','%s excerpt fallback'=>'%s രത്നച്ചുരുക്കത്തിന്റെ ബദൽ','%s includes every add-on sold here.'=>'ഇവിടെ വിൽക്കുന്ന എല്ലാ ആഡ്-ഓണുകളും %s ൽ ഉൾപ്പെടുന്നു.','%s is attending %s of the group %s.'=>'%s %s-ൽ പങ്കെടുക്കുന്നു (ഗ്രൂപ്പ്: %s).','%s is attending %s.'=>'%s %s-ൽ പങ്കെടുക്കുന്നു.','%s is replaced by username, %s is replaced by the user password and %s is replaced by a link to create a password.'=>'%s എന്നത് ഉപയോക്തൃനാമം കൊണ്ടും, %s എന്നത് ഉപയോക്താവിന്റെ രഹസ്യവാക്ക് കൊണ്ടും, %s എന്നത് രഹസ്യവാക്ക് സൃഷ്ടിക്കാനുള്ള ലിങ്ക് കൊണ്ടും മാറ്റിസ്ഥാപിക്കും.','%s is required.'=>'%s ആവശ്യമാണ്.','%s item'=>'%s ഇനം' . "\0" . '%s ഇനങ്ങൾ','%s list footer format'=>'%s പട്ടികയുടെ ഫൂട്ടർ ഫോർമാറ്റ്','%s list header format'=>'%s പട്ടികയുടെ ഹെഡർ ഫോർമാറ്റ്','%s list item format'=>'%s പട്ടിക ഇനത്തിന്റെ ഫോർമാറ്റ്','%s must be set to yes for this to work.'=>'ഇത് പ്രവർത്തിക്കാൻ %s അതെ എന്ന് സജ്ജമാക്കിയിരിക്കണം.','%s overrides all formatting choices, which will be be taken from the settings defined on this page. If you want to override only certain formatting, choose the %s instead.'=>'%s എല്ലാ ഫോർമാറ്റിംഗ് തിരഞ്ഞെടുപ്പുകളെയും അസാധുവാക്കുന്നു, അവ ഈ താളിൽ നിർവചിച്ച ക്രമീകരണങ്ങളിൽ നിന്ന് എടുക്കും. ചില ഫോർമാറ്റിംഗ് മാത്രം അസാധുവാക്കണമെങ്കിൽ പകരം %s തിരഞ്ഞെടുക്കുക.','%s page'=>'%s താൾ','%s parameters will be permitted in shortcode.'=>'%s പാരാമീറ്ററുകൾ ഷോർട്ട്കോഡിൽ അനുവദിക്കപ്പെടും.','%s row'=>'%s വരി' . "\0" . '%s വരികൾ','%s successfully deleted'=>'%s വിജയകരമായി ഇല്ലാതാക്കി','%s successfully deleted.'=>'%s വിജയകരമായി ഇല്ലാതാക്കി.','%s successfully duplicated.'=>'%s വിജയകരമായി പകർത്തി.','%s users cancelled bookings.'=>'%s ഉപയോക്താക്കൾ ബുക്കിംഗുകൾ റദ്ദാക്കി.','%s will be replaced by a link to your site privacy policy page.'=>'%s നിങ്ങളുടെ സൈറ്റ് സ്വകാര്യതാനയ താളിലേക്കുള്ള ലിങ്ക് ഉപയോഗിച്ച് മാറ്റിസ്ഥാപിക്കപ്പെടും.','%s will not be attending %s anymore.'=>'%s ഇനി %s-ൽ പങ്കെടുക്കില്ല.','%s will not be attending %s of group %s anymore.'=>'%s ഇനി %s-ൽ പങ്കെടുക്കില്ല (ഗ്രൂപ്പ്: %s).','(New)'=>'(പുതിയത്)','(always available)'=>'(എപ്പോഴും ലഭ്യമാണ്)','(not applicable with event ownership on presently, coming soon!)'=>'(ഇവന്റ് ഉടമസ്ഥത ഓണായിരിക്കുമ്പോൾ നിലവിൽ ബാധകമല്ല, ഉടൻ വരുന്നു!)','1,2,3 or 2 (0 = all)'=>'1,2,3 അല്ലെങ്കിൽ 2 (0 = എല്ലാം)','1. Match columns'=>'1. കോളങ്ങൾ പൊരുത്തപ്പെടുത്തുക','2 for every second day, week, month or year. Leave empty for every one.'=>'ഓരോ രണ്ടാം ദിവസത്തിനും, ആഴ്ചയ്ക്കും, മാസത്തിനും അല്ലെങ്കിൽ വർഷത്തിനും 2. എല്ലാറ്റിനുമാണെങ്കിൽ ശൂന്യമായി വിടുക.','2. Options'=>'2. ഓപ്ഷനുകൾ','3. Preview'=>'3. പ്രിവ്യൂ','<a href="%s">See some more information</a> on how %s work when overriding with formats.'=>'ഫോർമാറ്റുകൾ ഉപയോഗിച്ച് മറികടക്കുമ്പോൾ %s എങ്ങനെ പ്രവർത്തിക്കുന്നു എന്നതിനെക്കുറിച്ച് <a href="%s">കൂടുതൽ വിവരങ്ങൾ കാണുക</a>.','<a href="%s">Visit our blog</a> for the latest news about recent updates.'=>'സമീപകാല അപ്‌ഡേറ്റുകളെക്കുറിച്ചുള്ള ഏറ്റവും പുതിയ വാർത്തകൾക്കായി <a href="%s">ഞങ്ങളുടെ ബ്ലോഗ് സന്ദർശിക്കുക</a>.','<li>No events in this location</li>'=>'<li>ഈ സ്ഥലത്ത് ഇവന്റുകളൊന്നുമില്ല</li>','<p>Events Manager is ready to go! It is highly recommended you read the <a href=\'%s\'>Getting Started</a> guide on our site, as well as checking out the <a href=\'%s\'>Settings Page</a></p>'=>'<p>Events Manager ഉപയോഗിക്കാൻ തയ്യാറാണ്! ഞങ്ങളുടെ സൈറ്റിലെ <a href=\'%s\'>ആരംഭിക്കാനുള്ള</a> ഗൈഡ് വായിക്കാനും <a href=\'%s\'>ക്രമീകരണ താൾ</a> പരിശോധിക്കാനും ശുപാർശ ചെയ്യുന്നു</p>','<strong>ERROR</strong>: Couldn&#8217;t register you... please contact the <a href="mailto:%s">webmaster</a> !'=>'<strong>പിശക്</strong>: നിങ്ങളെ രജിസ്റ്റർ ചെയ്യാൻ കഴിഞ്ഞില്ല... ദയവായി <a href="mailto:%s">വെബ്‌മാസ്റ്ററെ</a> ബന്ധപ്പെടുക!','<strong>ERROR</strong>: Please enter a username.'=>'<strong>തെറ്റ്</strong>: യുസർ നെയിം നൽകുക','<strong>ERROR</strong>: Please type your e-mail address.'=>'<strong>പിശക്</strong>: ദയവായി നിങ്ങളുടെ ഇ-മെയിൽ വിലാസം ടൈപ്പ് ചെയ്യുക.','<strong>ERROR</strong>: The email address isn&#8217;t correct.'=>'<strong>തെറ്റ്</strong>: ഇമെയിൽ വിലാസം തെറ്റാണ്.','<strong>ERROR</strong>: This email is already registered, please choose another one.'=>'<strong>തെറ്റ്</strong>: ഈ ഇമെയിൽ വിലാസം ഉപയോകത്തിൽ ഉണ്ട്. ദയവായി മറ്റൊരു ഇമെയിൽ വിലാസം നൽകുക.','<strong>ERROR</strong>: This username is already registered, please choose another one.'=>'<strong>പിശക്</strong>: ഈ ഉപയോക്തൃനാമം ഇതിനകം രജിസ്റ്റർ ചെയ്തിട്ടുണ്ട്, ദയവായി മറ്റൊന്ന് തിരഞ്ഞെടുക്കുക.','<strong>ERROR</strong>: This username is invalid because it uses illegal characters. Please enter a valid username.'=>'<strong>തെറ്റ്</strong>: ഈ  യുസർ നെയിം അനുവതിനിയം അല്ല. ദയവായി വാലിഡ്‌ ആയ ഒരു യുസർ നെയിം നൽകുക.','<strong>Notes:</strong> Ticket availability not taken into account (i.e. you can overbook). Emails are not resent automatically.'=>'<strong>കുറിപ്പുകള്‍:</strong> ടിക്കറ്റ് ലഭ്യത പരിഗണിക്കില്ല (അതായത് ഓവർബുക്ക് ചെയ്യാം). ഇമെയിലുകൾ സ്വയമേവ വീണ്ടും അയയ്ക്കില്ല.','<strong>Notes:</strong> Ticket availability not taken into account when approving new bookings (i.e. you can overbook).'=>'<strong>കുറിപ്പുകള്‍:</strong> പുതിയ ബുക്കിംഗുകൾ അംഗീകരിക്കുമ്പോൾ ടിക്കറ്റ് ലഭ്യത പരിഗണിക്കില്ല (അതായത് ഓവർബുക്ക് ചെയ്യാം).','<strong>Warning : </strong> By enabling this, registered users will not be able to see bookings they make as guests in their "My Bookings" page.'=>'<strong>മുന്നറിയിപ്പ് : </strong> ഇത് പ്രവർത്തനക്ഷമമാക്കുന്നതിലൂടെ, രജിസ്റ്റർ ചെയ്ത ഉപയോക്താക്കൾക്ക് അതിഥികളായി നടത്തുന്ന ബുക്കിംഗുകൾ അവരുടെ "എന്റെ ബുക്കിംഗുകൾ" പേജിൽ കാണാൻ കഴിയില്ല.','<strong>Warning : </strong> Various features afforded to users with an account will not be available, e.g. viewing bookings. Once you enable this and select a user, modifying these values will prevent older non-user bookings from displaying the correct information.'=>'<strong>മുന്നറിയിപ്പ് : </strong> ബുക്കിംഗുകൾ കാണുന്നത് പോലെ, അക്കൗണ്ടുള്ള ഉപയോക്താക്കൾക്ക് ലഭിക്കുന്ന വിവിധ സവിശേഷതകൾ ലഭ്യമാകില്ല. ഇത് പ്രവർത്തനക്ഷമമാക്കി ഒരു ഉപയോക്താവിനെ തിരഞ്ഞെടുത്തുകഴിഞ്ഞാൽ, ഈ മൂല്യങ്ങൾ മാറ്റുന്നത് പഴയ ഉപയോക്താവില്ലാത്ത ബുക്കിംഗുകൾ ശരിയായ വിവരങ്ങൾ കാണിക്കുന്നത് തടയും.','A booking intent cannot have its status changed.'=>'ഒരു ബുക്കിംഗ് ഉദ്ദേശ്യത്തിന്റെ സ്ഥിതി മാറ്റാൻ കഴിയില്ല.','A booking was cancelled'=>'ഒരു ബുക്കിംഗ് റദ്ദാക്കി','A booking\'s payment gateway is set when the booking is made and cannot be changed.'=>'ഒരു ബുക്കിംഗിന്റെ പേയ്‌മെന്റ് ഗേറ്റ്‌വേ ബുക്കിംഗ് നടത്തുമ്പോൾ നിശ്ചയിക്കപ്പെടുന്നതാണ്, അത് മാറ്റാൻ കഴിയില്ല.','A guest-accessible cancellation flow for the EU statutory <strong>right of withdrawal</strong>. Enable this only if you sell to consumers who have a right of withdrawal — <strong>fixed-date events are generally exempt</strong>. Events Manager provides the mechanism; you supply your own legal withdrawal policy text below.'=>'പിന്മാറാനുള്ള EU നിയമപരമായ <strong>അവകാശത്തിനായി</strong> അതിഥികൾക്ക് ഉപയോഗിക്കാവുന്ന ഒരു റദ്ദാക്കൽ രീതി. പിന്മാറാനുള്ള അവകാശമുള്ള ഉപഭോക്താക്കൾക്ക് നിങ്ങൾ വിൽക്കുന്നുണ്ടെങ്കിൽ മാത്രം ഇത് പ്രവർത്തനക്ഷമമാക്കുക — <strong>നിശ്ചിത തീയതിയുള്ള ഇവന്റുകൾക്ക് സാധാരണയായി ഇളവുണ്ട്</strong>. Events Manager സംവിധാനം നൽകുന്നു; നിങ്ങളുടെ സ്വന്തം നിയമപരമായ പിന്മാറൽ നയ ടെക്സ്റ്റ് ചുവടെ നൽകുക.','A hybrid event needs a physical venue.'=>'ഒരു ഹൈബ്രിഡ് ഇവന്റിന് ഒരു ഭൗതിക വേദി ആവശ്യമാണ്.','A list of further dates, such as 2027-03-11|2027-03-18, used alone or with a rule.'=>'2027-03-11|2027-03-18 പോലുള്ള കൂടുതൽ തീയതികളുടെ പട്ടിക, ഒറ്റയ്ക്കോ ഒരു നിയമത്തോടൊപ്പമോ ഉപയോഗിക്കാം.','A location with this name is already on this site (location %d).'=>'ഈ പേരിലുള്ള ഒരു സ്ഥലം ഈ സൈറ്റിൽ ഇതിനകം ഉണ്ട് (സ്ഥലം %d).','A location with this name is already on this site.'=>'ഈ പേരിലുള്ള ഒരു സ്ഥലം ഈ സൈറ്റിൽ ഇതിനകം ഉണ്ട്.','A new event has been published by #_CONTACTNAME.<br/>Name : #_EVENTNAME <br/>Date : #_EVENTDATES <br/>Time : #_EVENTTIMES <br/>Edit this event - #_EDITEVENTURL <br/> View this event - #_EVENTURL'=>'#_CONTACTNAME ഒരു പുതിയ ഇവന്റ് പ്രസിദ്ധീകരിച്ചിരിക്കുന്നു.<br/>പേര് : #_EVENTNAME <br/>തീയതി : #_EVENTDATES <br/>സമയം : #_EVENTTIMES <br/>ഈ ഇവന്റ് തിരുത്തുക - #_EDITEVENTURL <br/> ഈ ഇവന്റ് കാണുക - #_EVENTURL','A new event has been submitted by #_CONTACTNAME.<br/>Name : #_EVENTNAME <br/>Date : #_EVENTDATES <br/>Time : #_EVENTTIMES <br/>Please visit #_EDITEVENTURL to review this event for approval.'=>'#_CONTACTNAME ഒരു പുതിയ ഇവന്റ് സമർപ്പിച്ചിരിക്കുന്നു.<br/>പേര് : #_EVENTNAME <br/>തീയതി : #_EVENTDATES <br/>സമയം : #_EVENTTIMES <br/>അംഗീകാരത്തിനായി ഈ ഇവന്റ് പരിശോധിക്കാൻ #_EDITEVENTURL സന്ദർശിക്കുക.','A new event was created'=>'ഒരു പുതിയ ഇവന്റ് ഉണ്ടാക്കി','A new user account has been created for you. Please check your email for access details.'=>'നിങ്ങൾക്കായി ഒരു പുതിയ ഉപയോക്തൃ അക്കൗണ്ട് ഉണ്ടാക്കിയിട്ടുണ്ട്. ആക്സസ് വിവരങ്ങൾക്കായി ദയവായി നിങ്ങളുടെ ഇമെയിൽ പരിശോധിക്കുക.','A previously published event has been modified by #_CONTACTNAME, and this event is now unpublished and pending your approval.<br/>Name : #_EVENTNAME <br/>Date : #_EVENTDATES <br/>Time : #_EVENTTIMES <br/>Please visit #_EDITEVENTURL to review this event for approval.'=>'മുമ്പ് പ്രസിദ്ധീകരിച്ച ഒരു ഇവന്റ് #_CONTACTNAME പരിഷ്കരിച്ചു, ഈ ഇവന്റ് ഇപ്പോൾ പ്രസിദ്ധീകരിക്കാത്തതും നിങ്ങളുടെ അംഗീകാരത്തിനായി കാത്തിരിക്കുന്നതുമാണ്.<br/>പേര് : #_EVENTNAME <br/>തീയതി : #_EVENTDATES <br/>സമയം : #_EVENTTIMES <br/>അംഗീകാരത്തിനായി ഈ ഇവന്റ് പരിശോധിക്കാൻ #_EDITEVENTURL സന്ദർശിക്കുക.','A repeating event needs a repeat-until date or a number of times.'=>'ആവർത്തിക്കുന്ന ഇവന്റിന് ആവർത്തന അവസാന തീയതിയോ ആവർത്തന എണ്ണമോ ആവശ്യമാണ്.','A test email will be sent to your account email - %s'=>'നിങ്ങളുടെ അക്കൗണ്ട് ഇമെയിലിലേക്ക് ഒരു ടെസ്റ്റ് ഇമെയിൽ അയയ്ക്കും - %s','A token is required.'=>'ഒരു ടോക്കൺ ആവശ്യമാണ്.','A user cancelled a booking'=>'ഒരു ഉപയോക്താവ് ഒരു ബുക്കിംഗ് റദ്ദാക്കി','A valid Expo push token is required.'=>'സാധുവായ ഒരു Expo പുഷ് ടോക്കൺ ആവശ്യമാണ്.','A valid blog ID must be provided, you can only reset one blog at a time.'=>'സാധുവായ ഒരു ബ്ലോഗ് ഐഡി നൽകണം, ഒരു സമയം ഒരു ബ്ലോഗ് മാത്രമേ പുനഃസജ്ജമാക്കാനാകൂ.','A valid email'=>'സാധുവായ ഒരു ഇമെയിൽ','A virtual event can hold its link back until shortly before it starts. Until then, visitors and attendees see a short text in place of the link, and join links sent to attendees only start working at that time.'=>'ഒരു വെർച്വൽ ഇവന്റിന് അതിന്റെ ലിങ്ക് ആരംഭിക്കുന്നതിന് തൊട്ടുമുമ്പ് വരെ മറച്ചുവയ്ക്കാം. അതുവരെ സന്ദർശകർക്കും പങ്കെടുക്കുന്നവർക്കും ലിങ്കിന് പകരം ഒരു ചെറിയ വാചകം കാണാം, പങ്കെടുക്കുന്നവർക്ക് അയച്ച ചേരാനുള്ള ലിങ്കുകൾ ആ സമയത്ത് മാത്രമേ പ്രവർത്തിക്കൂ.','AFTER the withdrawal period — please review carefully'=>'പിന്മാറൽ കാലയളവിന് ശേഷം — ശ്രദ്ധയോടെ അവലോകനം ചെയ്യുക','AI / MCP Setup'=>'AI / MCP സജ്ജീകരണം','Abbreviated weekdays'=>'ചുരുക്കിയ ആഴ്ച ദിവസങ്ങൾ','Abbreviated weekdays?'=>'ചുരുക്കിയ ആഴ്ച ദിവസങ്ങൾ?','Abilities that create, update, delete, or otherwise modify Events Manager data.'=>'Events Manager ഡാറ്റ സൃഷ്ടിക്കുകയോ അപ്ഡേറ്റ് ചെയ്യുകയോ ഇല്ലാതാക്കുകയോ മറ്റു വിധത്തിൽ മാറ്റം വരുത്തുകയോ ചെയ്യുന്ന കഴിവുകൾ.','Access'=>'ആക്സസ്','Accordion'=>'അക്കോഡിയൻ','Account Connection'=>'അക്കൗണ്ട് കണക്ഷൻ','Acknowledgment email'=>'കൈപ്പറ്റൽ ഇമെയിൽ','Acknowledgment email body'=>'കൈപ്പറ്റൽ ഇമെയിൽ ബോഡി','Acknowledgment email subject'=>'കൈപ്പറ്റൽ ഇമെയിൽ വിഷയം','Actions'=>'പ്രവൃത്തികൾ','Activate license'=>'ലൈസൻസ് സജീവമാക്കുക','Activate plugin'=>'പ്ലഗിൻ സജീവമാക്കുക','Active'=>'സജീവമായ','Add %s'=>'%s ചേർക്കുക','Add Dates '=>'തീയതികൾ ചേർക്കുക ','Add Event'=>'ഇവന്റ് ചേർക്കുക','Add Location'=>'സ്ഥലം ചേർക്കുക','Add New'=>'പുതിയത് ചേർക്കുക','Add New %s'=>'പുതിയ %s ചേർക്കുക','Add New Archetype'=>'പുതിയ ആർക്കിടൈപ്പ് ചേർക്കുക','Add New Event'=>'പുതിയ ഇവന്റ് ചേർക്കുക','Add New Event Category'=>'പുതിയ ഇവന്റ് വിഭാഗം ചേർക്കുക','Add New Event Tag'=>'പുതിയ ഇവന്റ് ടാഗ് ചേർക്കുക','Add New Location'=>'പുതിയ സ്ഥലം ചേർക്കുക','Add New Repeating Event'=>'പുതിയ ആവർത്തിക്കുന്ന ഇവന്റ് ചേർക്കുക','Add Note'=>'കുറിപ്പ് ചേർക്കുക','Add Repeating Event'=>'ആവർത്തിക്കുന്ന ഇവന്റ് ചേർക്കുക','Add Reply-To booker?'=>'ബുക്ക് ചെയ്യുന്നയാളെ Reply-To ആയി ചേർക്കണോ?','Add Reply-To event owner?'=>'ഇവന്റ് ഉടമയെ Reply-To ആയി ചേർക്കണോ?','Add Time Slot'=>'ടൈം സ്ലോട്ട് ചേർക്കുക','Add To Calendar'=>'കലണ്ടറിൽ ചേർക്കുക','Add a negative number or minus sign to the start of the date interval to allow cancellations after events have started.'=>'ഇവന്റുകൾ ആരംഭിച്ചതിന് ശേഷവും റദ്ദാക്കൽ അനുവദിക്കാൻ തീയതി ഇടവേളയുടെ തുടക്കത്തിൽ ഒരു നെഗറ്റീവ് സംഖ്യയോ മൈനസ് ചിഹ്നമോ ചേർക്കുക.','Add a start or end date (or both) to impose time constraints on ticket availability. Leave either blank for no upper/lower limit.'=>'ടിക്കറ്റ് ലഭ്യതയ്ക്ക് സമയപരിധി ഏർപ്പെടുത്താൻ ഒരു ആരംഭ തീയതിയോ അവസാന തീയതിയോ (അല്ലെങ്കിൽ രണ്ടും) ചേർക്കുക. ഉയർന്നതോ താഴ്ന്നതോ ആയ പരിധി വേണ്ടെങ്കിൽ അത് ശൂന്യമായി വിടുക.','Add a tax rate to your ticket prices (entering 10 will add 10% to the ticket price).'=>'നിങ്ങളുടെ ടിക്കറ്റ് വിലകളിൽ ഒരു നികുതി നിരക്ക് ചേർക്കുക (10 നൽകിയാൽ ടിക്കറ്റ് വിലയോട് 10% ചേർക്കും).','Add any of these columns to an events file. A row with none of them filled in is a single event.'=>'ഇവന്റ് ഫയലിലേക്ക് ഈ കോളങ്ങളിൽ ഏതെങ്കിലും ചേർക്കുക. ഇവയൊന്നും പൂരിപ്പിക്കാത്ത വരി ഒറ്റ ഇവന്റാണ്.','Add br tags to HTML emails?'=>'HTML ഇമെയിലുകളിൽ br ടാഗുകൾ ചേർക്കണോ?','Add location'=>'സ്ഥലം ചേർക്കുക','Add new ticket'=>'പുതിയ ടിക്കറ്റ് ചേർക്കുക','Add or remove %s'=>'%s ചേർക്കുക അല്ലെങ്കിൽ ഒഴിവാക്കുക','Add or remove events'=>'ഇവന്റുകൾ ചേർക്കുക അല്ലെങ്കിൽ ഒഴിവാക്കുക','Add tax to ticket price?'=>'ടിക്കറ്റ് വിലയിൽ നികുതി ചേർക്കണോ?','Add to your table from the columns below.'=>'ചുവടെയുള്ള നിരകളിൽ നിന്ന് നിങ്ങളുടെ പട്ടികയിലേക്ക് ചേർക്കുക.','Add-ons'=>'ആഡ്-ഓണുകൾ','Add-ons and prices are up to date.'=>'ആഡ്-ഓണുകളും വിലകളും കാലികമാണ്.','Add-ons are separate plugins that work with the free Events Manager plugin, so you do not need Events Manager Pro to use them.'=>'ആഡ്-ഓണുകൾ സൗജന്യ Events Manager പ്ലഗിനിനൊപ്പം പ്രവർത്തിക്കുന്ന പ്രത്യേക പ്ലഗിനുകളാണ്, അതിനാൽ അവ ഉപയോഗിക്കാൻ Events Manager Pro ആവശ്യമില്ല.','Additional CSS'=>'കൂട്ടിച്ചേർത്ത CSS','Address'=>'വിലാസം','Address line 2'=>'വിലാസ വരി 2','Address only'=>'വിലാസം മാത്രം','Address:'=>'വിലാസം:','Adds a checkbox below the location options that limits results to events attendees can join virtually, including hybrid events.'=>'സ്ഥല ഓപ്ഷനുകൾക്ക് താഴെ ഒരു ചെക്ക്ബോക്സ് ചേർക്കുന്നു, ഇത് ഹൈബ്രിഡ് ഇവന്റുകൾ ഉൾപ്പെടെ പങ്കെടുക്കുന്നവർക്ക് വെർച്വലായി ചേരാൻ കഴിയുന്ന ഇവന്റുകളിലേക്ക് ഫലങ്ങൾ പരിമിതപ്പെടുത്തുന്നു.','Adds a guest-accessible withdrawal flow and, optionally, a site-wide footer link.'=>'അതിഥികൾക്ക് ഉപയോഗിക്കാവുന്ന ഒരു പിന്മാറൽ രീതിയും, ഓപ്ഷണലായി സൈറ്റ് മുഴുവൻ ഫൂട്ടർ ലിങ്കും ചേർക്കുന്നു.','Adds the time and the hidden text to the event editor, so each event can set its own. If not, every event uses the defaults below.'=>'ഇവന്റ് എഡിറ്ററിലേക്ക് സമയവും മറച്ച വാചകവും ചേർക്കുന്നു, അതിനാൽ ഓരോ ഇവന്റിനും സ്വന്തമായി സജ്ജമാക്കാം. ഇല്ലെങ്കിൽ എല്ലാ ഇവന്റുകളും താഴെയുള്ള സ്ഥിരമൂല്യങ്ങൾ ഉപയോഗിക്കും.','Admin Icon'=>'അഡ്മിൻ ഐക്കൺ','Admin Tools'=>'അഡ്മിൻ ഉപകരണങ്ങൾ','Administrator Email'=>'അഡ്മിനിസ്ട്രേറ്റർ ഇമെയിൽ','Advanced'=>'വിപുലമായത്','Advanced Mode'=>'അഡ്വാൻസ്ഡ് മോഡ്','Advanced Search Fields'=>'വിപുലമായ തിരയൽ ഫീൽഡുകൾ','Advanced search mode'=>'വിപുലമായ തിരയൽ മോഡ്','Advanced search style'=>'വിപുലമായ തിരയലിന്റെ സ്റ്റൈൽ','Advanced settings'=>'അഡ്വാൻസ്ഡ് ക്രമീകരണങ്ങൾ','After'=>'ശേഷം','All'=>'എല്ലാം','All %s'=>'എല്ലാ %s','All Ascending'=>'എല്ലാം ആരോഹണം','All Blogs'=>'എല്ലാ ബ്ലോഗുകളും','All Categories'=>'എല്ലാ വിഭാഗങ്ങളും','All Cities/Towns'=>'എല്ലാ നഗരങ്ങളും/പട്ടണങ്ങളും','All Countries'=>'എല്ലാ രാജ്യങ്ങളും','All Day'=>'ദിവസം മുഴുവൻ','All Day Message'=>'ദിവസം മുഴുവൻ എന്ന സന്ദേശം','All Descending'=>'എല്ലാം അവരോഹണം','All Event Categories'=>'എല്ലാ ഇവന്റ് വിഭാഗങ്ങളും','All Event Tags'=>'എല്ലാ ഇവന്റ് ടാഗുകളും','All Event Types'=>'എല്ലാ ഇവന്റ് തരങ്ങളും','All Events'=>'എല്ലാ ഇവന്റുകളും','All Regions'=>'എല്ലാ പ്രദേശങ്ങളും','All States'=>'എല്ലാ സംസ്ഥാനങ്ങളും','All Tags'=>'എല്ലാ ടാഗുകളും','All Time'=>'എല്ലാ കാലവും','All Timeslots'=>'എല്ലാ ടൈംസ്ലോട്ടുകളും','All confirmed and pending bookings will be emailed a general event cancellation notification.'=>'സ്ഥിരീകരിച്ചതും തീരുമാനിക്കപ്പെടാത്തതുമായ എല്ലാ ബുക്കിംഗുകൾക്കും ഒരു പൊതു ഇവന്റ് റദ്ദാക്കൽ അറിയിപ്പ് ഇമെയിലായി അയയ്ക്കും.','All countries text'=>'എല്ലാ രാജ്യങ്ങളും എന്ന ടെക്സ്റ്റ്','All day'=>'ദിവസം മുഴുവൻ','All day (yes or no)'=>'ദിവസം മുഴുവൻ (yes അല്ലെങ്കിൽ no)','All events'=>'എല്ലാ ഇവന്റുകളും','All events link text?'=>'എല്ലാ ഇവന്റുകളും ലിങ്ക് ടെക്സ്റ്റ്?','All events will be moved to trash.'=>'എല്ലാ ഇവന്റുകളും ചവറ്റുകുട്ടയിലേക്ക് മാറ്റും.','All options below relate to data that may have been submitted by or collected from the user requesting their personal data, which would also include events and locations where they are the author.'=>'താഴെയുള്ള എല്ലാ ഓപ്ഷനുകളും, തങ്ങളുടെ വ്യക്തിഗത ഡാറ്റ അഭ്യർത്ഥിക്കുന്ന ഉപയോക്താവ് സമർപ്പിച്ചതോ അവരിൽ നിന്ന് ശേഖരിച്ചതോ ആയ ഡാറ്റയുമായി ബന്ധപ്പെട്ടതാണ്, അവർ ലേഖകരായ ഇവന്റുകളും സ്ഥലങ്ങളും ഇതിൽ ഉൾപ്പെടും.','All our sold add-ons'=>'ഞങ്ങൾ വിൽക്കുന്ന എല്ലാ ആഡ്-ഓണുകളും','All regions text'=>'എല്ലാ പ്രദേശങ്ങളും എന്ന ടെക്സ്റ്റ്','All settings, events and bookings for every site on this network will be permanently deleted. This cannot be undone.'=>'ഈ നെറ്റ്‌വർക്കിലെ എല്ലാ സൈറ്റുകളുടെയും ക്രമീകരണങ്ങൾ, ഇവന്റുകൾ, ബുക്കിംഗുകൾ എന്നിവ എന്നെന്നേക്കുമായി നീക്കം ചെയ്യപ്പെടും. ഇത് പഴയപടിയാക്കാൻ കഴിയില്ല.','All states text'=>'എല്ലാ സംസ്ഥാനങ്ങളും എന്ന ടെക്സ്റ്റ്','All towns/cities text'=>'എല്ലാ പട്ടണങ്ങളും/നഗരങ്ങളും എന്ന ടെക്സ്റ്റ്','All translations of this event will be detached from the recurring event.'=>'ഈ ഇവന്റിന്റെ എല്ലാ വിവർത്തനങ്ങളും ആവർത്തിക്കുന്ന ഇവന്റിൽ നിന്ന് വേർപെടുത്തും.','All your settings and events will be permanently deleted. This cannot be undone.'=>'നിങ്ങളുടെ എല്ലാ ക്രമീകരണങ്ങളും ഇവന്റുകളും എന്നെന്നേക്കുമായി നീക്കം ചെയ്യപ്പെടും. ഇത് പഴയപടിയാക്കാൻ കഴിയില്ല.','All your settings, including email templates and template formats for Events Manager will be deleted.'=>'ഇമെയിൽ ടെംപ്ലേറ്റുകളും Events Manager-ന്റെ ടെംപ്ലേറ്റ് ഫോർമാറ്റുകളും ഉൾപ്പെടെ നിങ്ങളുടെ എല്ലാ ക്രമീകരണങ്ങളും നീക്കം ചെയ്യപ്പെടും.','Allow %s to appear in the built-in search results.'=>'%s ബിൽറ്റ്-ഇൻ തിരയൽ ഫലങ്ങളിൽ ദൃശ്യമാകാൻ അനുവദിക്കുക.','Allow Maybe?'=>'\'ഒരുപക്ഷേ\' അനുവദിക്കണോ?','Allow Multiple Uploads'=>'ഒന്നിലധികം അപ്‌ലോഡുകൾ അനുവദിക്കുക','Allow RSVP Actions'=>'RSVP പ്രവൃത്തികൾ അനുവദിക്കുക','Allow WordPress post-style archives.'=>'WordPress പോസ്റ്റ്-ശൈലിയിലുള്ള ആർക്കൈവുകൾ അനുവദിക്കുക.','Allow anonymous event submissions?'=>'അജ്ഞാത ഇവന്റ് സമർപ്പണങ്ങൾ അനുവദിക്കണോ?','Allow bookings with registered emails?'=>'രജിസ്റ്റർ ചെയ്ത ഇമെയിലുകൾ ഉപയോഗിച്ചുള്ള ബുക്കിംഗുകൾ അനുവദിക്കണോ?','Allow double bookings?'=>'ഡബിൾ ബുക്കിംഗുകൾ അനുവദിക്കണോ?','Allow format shortcode parameters?'=>'ഫോർമാറ്റ് ഷോർട്ട്കോഡ് പാരാമീറ്ററുകൾ അനുവദിക്കണോ?','Allow guest bookings?'=>'ഗസ്റ്റ് ബുക്കിംഗുകൾ അനുവദിക്കണോ?','Allow overbooking when approving?'=>'അംഗീകരിക്കുമ്പോൾ ഓവർബുക്കിംഗ് അനുവദിക്കണോ?','Allow subsites to create their own'=>'സബ്സൈറ്റുകൾക്ക് സ്വന്തമായി സൃഷ്ടിക്കാൻ അനുവദിക്കുക','Allow users to respond with a \'Maybe\' status rather than Attending or Not Attending'=>'പങ്കെടുക്കുന്നു അല്ലെങ്കിൽ പങ്കെടുക്കുന്നില്ല എന്നതിന് പകരം \'ഒരുപക്ഷേ\' എന്ന സ്ഥിതിയിൽ പ്രതികരിക്കാൻ ഉപയോക്താക്കളെ അനുവദിക്കുക','Allowed Extensions'=>'അനുവദനീയമായ എക്സ്റ്റൻഷനുകൾ','Already Booked'=>'ഇതിനകം ബുക്ക് ചെയ്തു','Already attending'=>'ഇതിനകം പങ്കെടുക്കുന്നു','Already booked'=>'ഇതിനകം ബുക്ക് ചെയ്തു','Already have a license? Download the plugin from %s, upload it under Plugins > Add New Plugin, then activate your license from its settings.'=>'ഇതിനകം ലൈസൻസ് ഉണ്ടോ? %s ൽ നിന്ന് പ്ലഗിൻ ഡൗൺലോഡ് ചെയ്യുക, പ്ലഗിനുകൾ > പുതിയത് ചേർക്കുക എന്നതിൽ അപ്‌ലോഡ് ചെയ്യുക, തുടർന്ന് അതിന്റെ ക്രമീകരണങ്ങളിൽ നിന്ന് നിങ്ങളുടെ ലൈസൻസ് സജീവമാക്കുക.','Already migrated: %s'=>'ഇതിനകം മൈഗ്രേറ്റ് ചെയ്തത്: %s','Also, the following will occur:'=>'കൂടാതെ, ഇനിപ്പറയുന്നവയും സംഭവിക്കും:','Always check the latest stable version?'=>'എപ്പോഴും ഏറ്റവും പുതിയ സ്റ്റേബിൾ പതിപ്പ് പരിശോധിക്കണോ?','Always show and ask for consent'=>'എപ്പോഴും കാണിച്ച് സമ്മതം ചോദിക്കുക','An email will be sent to an administrator of your choice when an event is published by users who are not administrators.'=>'അഡ്മിനിസ്ട്രേറ്റർമാരല്ലാത്ത ഉപയോക്താക്കൾ ഒരു ഇവന്റ് പ്രസിദ്ധീകരിക്കുമ്പോൾ നിങ്ങൾ തിരഞ്ഞെടുക്കുന്ന ഒരു അഡ്മിനിസ്ട്രേറ്റർക്ക് ഇമെയിൽ അയയ്ക്കും.','An email will be sent to the event contact if someone cancels their booking.'=>'ആരെങ്കിലും ബുക്കിംഗ് റദ്ദാക്കിയാൽ ഇവന്റ് കോൺടാക്റ്റിന് ഇമെയിൽ അയയ്ക്കും.','An email will be sent to the event owner when their event is approved. Users requiring event approval do not have the <code>publish_events</code> capability.'=>'ഇവന്റ് ഉടമയുടെ ഇവന്റ് അംഗീകരിക്കുമ്പോൾ അവർക്ക് ഇമെയിൽ അയയ്ക്കും. ഇവന്റ് അംഗീകാരം ആവശ്യമുള്ള ഉപയോക്താക്കൾക്ക് <code>publish_events</code> ശേഷി ഉണ്ടായിരിക്കില്ല.','An email will be sent to your administrator emails when an event is submitted and pending approval.'=>'ഒരു ഇവന്റ് സമർപ്പിക്കുകയും അംഗീകാരത്തിനായി തീരുമാനമാകാതെ നിൽക്കുകയും ചെയ്യുമ്പോൾ നിങ്ങളുടെ അഡ്മിനിസ്ട്രേറ്റർ ഇമെയിലുകളിലേക്ക് ഒരു ഇമെയിൽ അയയ്ക്കും.','An error has occurred, not all sites were upgraded successfully.'=>'ഒരു പിശക് ഉണ്ടായി, എല്ലാ സൈറ്റുകളും വിജയകരമായി അപ്‌ഗ്രേഡ് ചെയ്തില്ല.','An error occurred.'=>'ഒരു പിശക് സംഭവിച്ചു.','An event with no bookings.'=>'ബുക്കിംഗുകൾ ഇല്ലാത്ത ഒരു ഇവന്റ്.','An event with this name and start is already on this site (event %d).'=>'ഈ പേരും ആരംഭവുമുള്ള ഒരു ഇവന്റ് ഈ സൈറ്റിൽ ഇതിനകം ഉണ്ട് (ഇവന്റ് %d).','An import is running. Wait for it to finish, or pause it first.'=>'ഒരു ഇമ്പോർട്ട് പ്രവർത്തിക്കുകയാണ്. അത് പൂർത്തിയാകുന്നതുവരെ കാത്തിരിക്കുക, അല്ലെങ്കിൽ ആദ്യം താൽക്കാലികമായി നിർത്തുക.','An organizer with this name is already on this site.'=>'ഈ പേരിലുള്ള ഒരു സംഘാടകൻ ഈ സൈറ്റിൽ ഇതിനകം ഉണ്ട്.','And much more'=>'കൂടാതെ മറ്റു പലതും','Anonymous Submitter Info'=>'അജ്ഞാത സമർപ്പകന്റെ വിവരം','Anonymous event submissions'=>'അജ്ഞാത ഇവന്റ് സമർപ്പണങ്ങൾ','Anonymous submitters cannot see or modify their event once submitted. You can customize the success message they see here.'=>'അജ്ഞാത സമർപ്പകർക്ക് സമർപ്പിച്ചശേഷം അവരുടെ ഇവന്റ് കാണാനോ മാറ്റാനോ കഴിയില്ല. അവർ കാണുന്ന വിജയ സന്ദേശം ഇവിടെ ഇഷ്‌ടാനുസൃതമാക്കാം.','Another request is already updating this online location.'=>'മറ്റൊരു അഭ്യർത്ഥന ഇതിനകം ഈ ഓൺലൈൻ സ്ഥലം അപ്ഡേറ്റ് ചെയ്യുകയാണ്.','Any Type'=>'ഏത് തരവും','Appears as the first default search option.'=>'ആദ്യത്തെ സ്വാഭാവിക തിരയൽ ഓപ്ഷനായി ദൃശ്യമാകുന്നു.','Appears as the label for this search option.'=>'ഈ തിരയൽ ഓപ്ഷന്റെ ലേബലായി ദൃശ്യമാകുന്നു.','Appears on the text search filter above the categories list.'=>'വിഭാഗങ്ങളുടെ പട്ടികയ്ക്ക് മുകളിലുള്ള ടെക്സ്റ്റ് തിരയൽ ഫിൽട്ടറിൽ ദൃശ്യമാകുന്നു.','Appears on the text search filter above the tags list.'=>'ടാഗുകളുടെ പട്ടികയ്ക്ക് മുകളിലുള്ള ടെക്സ്റ്റ് തിരയൽ ഫിൽട്ടറിൽ ദൃശ്യമാകുന്നു.','Appears within the input box.'=>'ഇൻപുട്ട് ബോക്സിനുള്ളിൽ ദൃശ്യമാകുന്നു.','Apply global capabilities?'=>'ഗ്ലോബൽ കഴിവുകൾ ബാധകമാക്കണോ?','Approval Required?'=>'അംഗീകാരം ആവശ്യമാണോ?','Approve'=>'ശരിവയ്‌ക്കുക','Approved'=>'അംഗീകരിച്ചു','Archetype'=>'ആർക്കിടൈപ്പ്','Archetypes UI Builder'=>'ആർക്കിടൈപ്പ്സ് യുഐ ബിൽഡർ','Are current events past events?'=>'നിലവിലുള്ള ഇവന്റുകൾ കഴിഞ്ഞ ഇവന്റുകളാണോ?','Are you sure you want to cancel your booking?'=>'നിങ്ങളുടെ ബുക്കിംഗ് റദ്ദാക്കണമെന്ന് ഉറപ്പാണോ?','Are you sure you want to continue?'=>'തുടരണമെന്ന് ഉറപ്പാണോ?','Are you sure you want to convert all repeating events into recurring events?'=>'എല്ലാ ആവർത്തന ഇവന്റുകളും ആവർത്തിക്കുന്ന ഇവന്റുകളാക്കി മാറ്റണമെന്ന് ഉറപ്പാണോ?','Are you sure you want to convert this repeating event?'=>'ഈ ആവർത്തിക്കുന്ന ഇവന്റ് പരിവർത്തനം ചെയ്യണമെന്ന് ഉറപ്പാണോ?','Are you sure you want to delete all recurrences of this event?'=>'ഈ ഇവന്റിന്റെ എല്ലാ ആവർത്തനങ്ങളും ഇല്ലാതാക്കണമെന്ന് ഉറപ്പാണോ?','Are you sure you want to delete this archetype? This action cannot be undone.'=>'ഈ ആർക്കിടൈപ്പ് ഇല്ലാതാക്കണമെന്ന് ഉറപ്പാണോ? ഈ പ്രവൃത്തി പഴയപടിയാക്കാൻ കഴിയില്ല.','Are you sure you want to delete this file? It will be deleted upon submission.'=>'ഈ ഫയൽ ഇല്ലാതാക്കണമെന്ന് ഉറപ്പാണോ? സമർപ്പിക്കുമ്പോൾ ഇത് ഇല്ലാതാക്കപ്പെടും.','Are you sure you want to delete this item? This action cannot be undone.'=>'ഈ ഇനം ഇല്ലാതാക്കണമെന്ന് ഉറപ്പാണോ? ഈ നടപടി പഴയപടിയാക്കാൻ കഴിയില്ല.','Are you sure you want to delete this ticket?'=>'ഈ ടിക്കറ്റ് ഇല്ലാതാക്കണമെന്ന് ഉറപ്പാണോ?','Are you sure you want to delete this ticket? All bookings related to this ticket will be deleted once you save this %s.'=>'ഈ ടിക്കറ്റ് ഇല്ലാതാക്കണമെന്ന് ഉറപ്പാണോ? ഈ %s സൂക്ഷിക്കുമ്പോൾ ഈ ടിക്കറ്റുമായി ബന്ധപ്പെട്ട എല്ലാ ബുക്കിംഗുകളും ഇല്ലാതാക്കപ്പെടും.','Are you sure you want to delete?'=>'ഇല്ലാതാക്കണമെന്ന് ഉറപ്പാണോ?','Are you sure you want to delete? This action cannot be undone.'=>'ഇല്ലാതാക്കണമെന്ന് ഉറപ്പാണോ? ഈ നടപടി പഴയപടിയാക്കാൻ കഴിയില്ല.','Are you sure you want to detach this event? By doing so, this event will be independent of the recurring set of events.'=>'ഈ ഇവന്റ് വേർപെടുത്തണമെന്ന് ഉറപ്പാണോ? ഇത് ചെയ്യുന്നതോടെ, ഈ ഇവന്റ് ആവർത്തിക്കുന്ന ഇവന്റുകളുടെ ശ്രേണിയിൽ നിന്ന് സ്വതന്ത്രമാകും.','Are you sure you want to disable bookings? If you do this and save, you will lose all previous bookings. If you wish to prevent further bookings, reduce the number of spaces available to the amount of bookings you currently have'=>'ബുക്കിംഗുകൾ പ്രവർത്തനരഹിതമാക്കണമെന്ന് ഉറപ്പാണോ? ഇത് ചെയ്ത് സൂക്ഷിച്ചാൽ, മുമ്പത്തെ എല്ലാ ബുക്കിംഗുകളും നിങ്ങൾക്ക് നഷ്ടമാകും. കൂടുതൽ ബുക്കിംഗുകൾ തടയണമെങ്കിൽ, ലഭ്യമായ സീറ്റുകളുടെ എണ്ണം നിലവിലുള്ള ബുക്കിംഗുകളുടെ എണ്ണമായി കുറയ്ക്കുക','Are you sure you want to proceed? We recommend you back up your database first, just in case!'=>'തുടരണമെന്ന് ഉറപ്പാണോ? മുൻകരുതലായി ആദ്യം നിങ്ങളുടെ ഡാറ്റാബേസ് ബാക്കപ്പ് ചെയ്യാൻ ഞങ്ങൾ ശുപാർശ ചെയ്യുന്നു!','Are you sure you want to reset Events Manager?'=>'Events Manager പുനഃസജ്ജമാക്കണമെന്ന് ഉറപ്പാണോ?','Are you sure you want to uninstall Events Manager?'=>'Events Manager അൺഇൻസ്റ്റാൾ ചെയ്യണമെന്ന് ഉറപ്പാണോ?','As a site admin, you see all group events, users will only be able to choose groups they are admins of.'=>'സൈറ്റ് അഡ്മിൻ എന്ന നിലയിൽ നിങ്ങൾ എല്ലാ ഗ്രൂപ്പ് ഇവന്റുകളും കാണുന്നു; ഉപയോക്താക്കൾക്ക് അവർ അഡ്മിനായ ഗ്രൂപ്പുകൾ മാത്രമേ തിരഞ്ഞെടുക്കാനാകൂ.','Ascending'=>'ആരോഹണ','Aside from pages we automatically generate and include certain jQuery files, if you are using Widgets, Shortcode or PHP to display specific items you may need to tell us where you are using them for them to work properly. Below are options for you to include specific jQuery dependencies only on certain pages.'=>'ഞങ്ങൾ സ്വയം സൃഷ്ടിക്കുന്ന താളുകൾക്കും ചില jQuery ഫയലുകൾക്കും പുറമെ, നിങ്ങൾ വിജറ്റുകളോ ഷോർട്ട്കോഡോ PHP യോ ഉപയോഗിച്ച് നിർദ്ദിഷ്ട ഇനങ്ങൾ പ്രദർശിപ്പിക്കുന്നുവെങ്കിൽ, അവ ശരിയായി പ്രവർത്തിക്കാൻ അവ എവിടെയാണ് ഉപയോഗിക്കുന്നതെന്ന് ഞങ്ങളെ അറിയിക്കേണ്ടി വന്നേക്കാം. നിർദ്ദിഷ്ട താളുകളിൽ മാത്രം jQuery ആശ്രയങ്ങൾ ഉൾപ്പെടുത്താനുള്ള ഓപ്ഷനുകൾ താഴെയുണ്ട്.','Attachment ID not found.'=>'അറ്റാച്ച്‌മെന്റ് ഐഡി കണ്ടെത്തിയില്ല.','Attendee %d'=>'പങ്കെടുക്കുന്നയാൾ %d','Attendee %s'=>'പങ്കെടുക്കുന്നയാൾ %s','Attendee (Per Space Booked)'=>'പങ്കെടുക്കുന്നയാൾ (ബുക്ക് ചെയ്ത ഓരോ സീറ്റിനും)','Attendee names, answers to attendee fields and check-in status are copied and kept with each ticket. Without Events Manager Pro they are not shown, so you will see each booking, its tickets and the person who booked.'=>'പങ്കെടുക്കുന്നവരുടെ പേരുകൾ, പങ്കെടുക്കുന്നവരുടെ ഫീൽഡുകളിലെ ഉത്തരങ്ങൾ, ചെക്ക്-ഇൻ സ്ഥിതി എന്നിവ പകർത്തി ഓരോ ടിക്കറ്റിനോടൊപ്പം സൂക്ഷിക്കുന്നു. Events Manager Pro ഇല്ലാതെ അവ കാണിക്കില്ല, അതിനാൽ ഓരോ ബുക്കിംഗും അതിന്റെ ടിക്കറ്റുകളും ബുക്ക് ചെയ്ത വ്യക്തിയെയും നിങ്ങൾ കാണും.','Attendees'=>'പങ്കെടുക്കുന്നവർ','Attending'=>'പങ്കെടുക്കുന്നു','Attributes'=>'വിശേഷണങ്ങൾ','AutoTLS'=>'ഓട്ടോടിഎൽഎസ്','Avail. Spaces'=>'ലഭ്യമായ സീറ്റുകൾ','Availability'=>'ലഭ്യത','Available'=>'ലഭ്യമാണ്','Available Archetypes'=>'ലഭ്യമായ ആർക്കിടൈപ്പുകൾ','Available Spaces'=>'ലഭ്യമായ സീറ്റുകൾ','Available for'=>'ലഭ്യമാകുന്നത്','Available from'=>'ലഭ്യമാകുന്നത്','Available spaces'=>'ലഭ്യമായ സീറ്റുകൾ','Available until'=>'ലഭ്യമായിരിക്കുന്നത് വരെ','Average Sale'=>'ശരാശരി വിൽപ്പന','Average Ticket'=>'ശരാശരി ടിക്കറ്റ്','Awaiting Online Payment'=>'ഓൺലൈൻ പേയ്‌മെന്റിനായി കാത്തിരിക്കുന്നു','Awaiting Payment'=>'പേയ്‌മെന്റിനായി കാത്തിരിക്കുന്നു','Bar Graph'=>'ബാർ ഗ്രാഫ്','Base Event Settings'=>'അടിസ്ഥാന ഇവന്റ് ക്രമീകരണങ്ങൾ','Base Location Settings'=>'അടിസ്ഥാന ലൊക്കേഷൻ ക്രമീകരണങ്ങൾ','Base font size'=>'അടിസ്ഥാന ഫോണ്ട് വലുപ്പം','Base font weight'=>'അടിസ്ഥാന ഫോണ്ട് വെയ്റ്റ്','Base line height'=>'അടിസ്ഥാന വരി ഉയരം','Basic HTML is allowed in ticket labels and descriptions.'=>'ടിക്കറ്റ് ലേബലുകളിലും വിവരണങ്ങളിലും അടിസ്ഥാന HTML അനുവദനീയമാണ്.','Basic Only'=>'അടിസ്ഥാനം മാത്രം','Be aware that some themes will not work with this option, if so (or you want to make your own changes), you can create a file named <code>single-%s.php</code> <a href=\'#\'>as shown on the WordPress codex</a>, and leave this set to Posts.'=>'ചില തീമുകൾ ഈ ഓപ്ഷനോടൊപ്പം പ്രവർത്തിക്കില്ല എന്ന് ശ്രദ്ധിക്കുക, അങ്ങനെയെങ്കിൽ (അല്ലെങ്കിൽ സ്വന്തം മാറ്റങ്ങൾ വരുത്തണമെങ്കിൽ) <a href=\'#\'>WordPress കോഡെക്സിൽ കാണിച്ചിരിക്കുന്നത് പോലെ</a> <code>single-%s.php</code> എന്ന പേരിൽ ഒരു ഫയൽ സൃഷ്ടിച്ച് ഇത് പോസ്റ്റുകൾ ആയി തന്നെ വിടുക.','Before'=>'മുമ്പ്','Before you save your changes, you can quickly send yourself a test email by clicking this button.'=>'മാറ്റങ്ങൾ സൂക്ഷിക്കുന്നതിന് മുമ്പ്, ഈ ബട്ടൺ ക്ലിക്ക് ചെയ്ത് നിങ്ങൾക്ക് തന്നെ വേഗത്തിൽ ഒരു ടെസ്റ്റ് ഇമെയിൽ അയയ്ക്കാം.','Below are translations for your location address. If left blank, the language of the original event will be used.'=>'നിങ്ങളുടെ സ്ഥല വിലാസത്തിന്റെ വിവർത്തനങ്ങൾ ചുവടെ. ശൂന്യമായി വിട്ടാൽ യഥാർത്ഥ ഇവന്റിന്റെ ഭാഷ ഉപയോഗിക്കും.','Below are translations for your tickets. If left blank, the language of the original event will be used.'=>'നിങ്ങളുടെ ടിക്കറ്റുകളുടെ വിവർത്തനങ്ങൾ ചുവടെ. ശൂന്യമായി വിട്ടാൽ യഥാർത്ഥ ഇവന്റിന്റെ ഭാഷ ഉപയോഗിക്കും.','Below you will find texts that will be displayed to users in various areas during the bookings process, particularly on booking forms.'=>'ബുക്കിംഗ് പ്രക്രിയയിൽ, പ്രത്യേകിച്ച് ബുക്കിംഗ് ഫോമുകളിൽ, ഉപയോക്താക്കൾക്ക് വിവിധ ഭാഗങ്ങളിൽ കാണിക്കുന്ന വാചകങ്ങൾ താഴെ കാണാം.','Block Editor (Gutenberg)'=>'ബ്ലോക്ക് എഡിറ്റർ (Gutenberg)','Block Editor development is still ongoing, switch back to the Classic Editor if you experience issues.'=>'ബ്ലോക്ക് എഡിറ്ററിന്റെ വികസനം ഇപ്പോഴും തുടരുകയാണ്, പ്രശ്നങ്ങൾ ഉണ്ടായാൽ ക്ലാസിക് എഡിറ്ററിലേക്ക് മടങ്ങുക.','Block editor layout'=>'ബ്ലോക്ക് എഡിറ്റർ ലേഔട്ട്','Blog Default Timezone'=>'ബ്ലോഗിന്റെ സ്വാഭാവികമായ സമയ മേഖല','Body Classes'=>'ബോഡി ക്ലാസുകൾ','Book Now'=>'ഇപ്പോൾ ബുക്ക് ചെയ്യുക','Book Now!'=>'ഇപ്പോൾ ബുക്ക് ചെയ്യുക!','Booked'=>'ബുക്ക് ചെയ്തത്','Booked Spaces'=>'ബുക്ക് ചെയ്ത സീറ്റുകൾ','Booked User Emails'=>'ബുക്ക് ചെയ്ത ഉപയോക്താവിന്റെ ഇമെയിലുകൾ','Booked/Available'=>'ബുക്ക് ചെയ്തത്/ലഭ്യമായത്','Booking'=>'ബുക്കിംഗ്','Booking %s'=>'ബുക്കിംഗ് %s','Booking %s.'=>'ബുക്കിംഗ് %s.','Booking Actions'=>'ബുക്കിംഗ് നടപടികൾ','Booking Cancellation Warning'=>'ബുക്കിംഗ് റദ്ദാക്കൽ മുന്നറിയിപ്പ്','Booking Cancelled'=>'ബുക്കിംഗ് റദ്ദാക്കി','Booking Chart'=>'ബുക്കിംഗ് ചാർട്ട്','Booking Comment'=>'ബുക്കിംഗ് അഭിപ്രായം','Booking Confirmation'=>'ബുക്കിംഗ് സ്ഥിരീകരണം','Booking Confirmed'=>'ബുക്കിംഗ് സ്ഥിരീകരിച്ചു','Booking Cut-Off Date'=>'ബുക്കിംഗ് അവസാന തീയതി','Booking Data'=>'ബുക്കിംഗ് ഡാറ്റ','Booking Date'=>'ബുക്കിംഗ് തീയതി','Booking Details'=